INSERT INTO `clinical_encounters` (`id`, `encounter_number`, `patient_id`, `provider_id`, `encounter_type`, `encounter_date`, `chief_complaint`, `history_of_present_illness`, `examination_findings`, `assessment_plan`, `status`) VALUES
(1, 'ENC-2024-00001', 1, 2, 'OPD', '2024-01-27 11:30:00', 'Acute chest heaviness and breathlessness on climbing stairs', 'Patient reports progressive exertional retrosternal discomfort since 3 days.', 'BP elevated, S1 S2 normal, no murmurs. Lungs clear.', 'Stable angina evaluation. Order Troponin-I and ECG.', 'COMPLETED'),
