(1, 1, 1, 1, 'Drug-Drug Critical Interaction Detected', 'Concomitant prescription of Aspirin with Enoxaparin (Clexane) increases high-potency gastrointestinal bleeding hazard.', 'CRITICAL', '2024-02-15 10:15:00', 2, 'Doctor reviewed: dose adjusted and gastro-protection added'),
(2, 1, 1, 3, 'Patient Penicillin Allergy Alert', 'Patient Rohit Mehta has registered severe allergy to Penicillin. Beta-lactam antibiotic prescription flagged.', 'CRITICAL', '2024-02-15 10:18:00', 2, 'Switched to non-penicillin alternative (Azithromycin)'),
(3, 3, 3, 2, 'Drug Interaction: NSAID + ARB', 'Telmisartan co-prescribed with Ibuprofen poses reversible nephrotoxicity and blunts BP reduction.', 'HIGH', '2024-03-10 11:45:00', 3, 'Advised patient on hydration; monitoring creatinine'),
(4, 7, 7, 5, 'Stage 2 Hypertensive Crisis Warning', 'Patient recorded blood pressure of 175/105 mmHg exceeding hypertensive emergency threshold.', 'HIGH', '2024-04-12 14:20:00', 2, 'Emergency anti-hypertensive administered stat'),
(5, 4, 4, 10, 'Aspirin Sensitivity Alert', 'Meera Iyer has severe bronchospastic reaction to Aspirin. NSAID avoided.', 'HIGH', '2024-05-02 09:40:00', 5, 'Prescribed safe alternative Paracetamol'),
(6, 10, 10, 5, 'Elevated Systolic Blood Pressure', 'Systolic reading 168 mmHg detected during OPD triage.', 'MEDIUM', '2024-06-18 16:30:00', 3, 'Acknowledged and repeated reading after 15 min rest'),
(7, 12, 12, 7, 'Critical Oxygen Saturation (SpO2)', 'Oxygen saturation 91.5% detected on room air. Acute respiratory workup needed.', 'CRITICAL', '2024-07-22 18:10:00', 3, 'Supplemental nasal oxygen initiated at 2L/min'),
(8, 13, 13, 3, 'Amoxicillin Allergy Override', 'Patient marked allergic to Amoxicillin. Prescription prevented by CPOE.', 'CRITICAL', '2024-08-05 10:05:00', 4, 'Cancelled order item; substituted with Cefixime'),
(9, 18, 18, 4, 'Iodinated Radiocontrast Caution', 'Patient marked allergic to CT contrast. Non-contrast study advised.', 'HIGH', '2024-09-11 12:50:00', 2, 'Non-contrast MRI ordered instead'),
